package com.servicedesk360.service;
import com.servicedesk360.dto.sla.*; import com.servicedesk360.entity.*; import com.servicedesk360.exception.*; import com.servicedesk360.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class SlaService{private final SlaPolicyRepository repo; private final CurrentUserService current; public SlaService(SlaPolicyRepository r,CurrentUserService c){repo=r;current=c;} @Transactional(readOnly=true) public List<SlaPolicyResponse> list(){return repo.findAllByTenantId(current.getRequiredUser().tenantId()).stream().map(SlaPolicyResponse::from).toList();} @Transactional public SlaPolicyResponse save(Long id,SlaPolicyRequest r){var me=current.getRequiredUser(); if(me.role()!=Role.TENANT_ADMIN)throw new UnauthorizedException("Tenant administrator role required"); SlaPolicy p=id==null?new SlaPolicy(me.tenantId(),r.priority(),r.firstResponseMinutes(),r.resolutionMinutes()):repo.findByIdAndTenantId(id,me.tenantId()).orElseThrow(()->new ResourceNotFoundException("SLA policy not found")); p.setFirstResponseMinutes(r.firstResponseMinutes());p.setResolutionMinutes(r.resolutionMinutes());p.setActive(r.active());return SlaPolicyResponse.from(repo.save(p));} public Deadline deadline(Long tenant,TicketPriority priority,Instant created){var p=repo.findByTenantIdAndPriorityAndActiveTrue(tenant,priority).orElse(null);return p==null?new Deadline(null,null):new Deadline(created.plusSeconds(p.getFirstResponseMinutes()*60L),created.plusSeconds(p.getResolutionMinutes()*60L));} public record Deadline(Instant firstResponseDueAt,Instant resolutionDueAt){}
}
